BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
I=[['拉丁 somnus → insomnis → insomnia','睡眠 → 无法入睡的 → 失眠'],['英语早期 insomnie → insomnia','借入后按拉丁形式调整拼写']]
W=[E('insomnia','英 /ɪnˈsɒmniə/；美 /ɪnˈsɑːmniə/','失眠','有时间睡，也想睡，却难以进入或保持睡眠。','借拉丁 insomnia，接 insomnis“无眠的”：in- 表否定，somnus 是睡眠。英语早先也写 insomnie，后来采用更接近拉丁语的 insomnia；现代可按 in- + somn- + -ia 记忆。',I,'失眠不一定是整夜一秒没睡，也可能是难以入睡、睡着后容易醒或难以获得良好睡眠。这个词说的是睡眠出了困难，不是因为主动熬夜而少睡。','have insomnia；suffer from insomnia；chronic insomnia。通常作不可数名词。','sleep deprivation 是睡眠不足，可能因为工作挤占睡觉时间；insomnia 强调即使有睡眠机会，也难以睡好。',('The survey asked participants about insomnia and daytime tiredness.','调查询问了参与者的失眠和白天疲倦情况。'),('Her diary describes several weeks of insomnia.','她的日记记录了持续数周的失眠。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/insomnia','https://www.etymonline.com/word/insomnia','https://www.nhlbi.nih.gov/health/insomnia']),
E('insomniac','英 /ɪnˈsɒmniæk/；美 /ɪnˈsɑːmniæk/','失眠者；失眠的','把失眠这种状态，换成有这种困扰的人。','英语 insomnia + -ac，形成形容词和人的名称。-ac 是这里的派生后缀，不要把结尾看成另一个完整单词。',I+[['英语 insomnia + -ac → insomniac','失眠的；经常难以入睡的人']],'名词 an insomniac 是一个经常难以睡着或睡好的人，复数 insomniacs。它也可作形容词，但日常更容易遇到名词用法。描述一个人偶尔晚睡，不必因此给他贴上这个标签。','an insomniac；a lifelong insomniac；insomniac nights〔文学表达〕。','a night owl 是习惯夜里活动的人，未必想睡却睡不着；an insomniac 强调睡眠困难。',('The novel follows an insomniac who walks through the city at night.','小说讲述了一位失眠者夜间在城里漫步的故事。'),('Several insomniacs described their experiences in the interview.','几位失眠者在访谈中讲述了自己的经历。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/insomniac','https://www.etymonline.com/word/insomnia','https://en.wiktionary.org/wiki/insomniac']),
E('somnolent','英 /ˈsɒmnələnt/；美 /ˈsɑːmnələnt/','昏昏欲睡的；懒洋洋的〔正式〕','眼皮越来越沉，整个人像快进入睡眠。','接拉丁 somnolentus“困倦的”，来自 somnus“睡眠”。英语有古法语 sompnolent/somnolent 中介，也有直接拉丁借入分析；旧拼写中的 p 后来依拉丁形式消失。',[['拉丁 somnus → somnolentus','睡眠 → 困倦、想睡的'],['古法语 sompnolent / somnolent；也有直接拉丁借入路线','进入中古英语 sompnolent'],['英语 somnolent','依拉丁形式调整拼写；困倦，或比喻地方懒洋洋']],'用在人身上，是困得快睡着；用在小镇、街道上，是安静缓慢、像没完全醒来。这类描写带文学色彩，日常说 sleepy 或 drowsy 更自然。','feel somnolent；a somnolent afternoon；a somnolent village。','insomnia 是难以睡着，somnolent 是很想睡；tired 范围更广，身体累不一定眼皮发沉。',('After the long journey, he sat in a somnolent silence.','长途旅行后，他困倦地坐着，一声不吭。'),('The square looked somnolent in the afternoon heat.','午后的热气中，广场显得懒洋洋的。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/somnolent','https://www.etymonline.com/word/somnolent'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C1366');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C1366');keep={w['word']for w in W};excluded={w:'按用户当前范围暂略：较罕见的睡眠专门术语或文学派生词，优先常见 insomnia 及相关阅读词。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
